#: Result downloads ask for CSV; the Accept header must match the job's content type.
_CSV = {"Accept": "text/csv"}
#: Bytes of a spooled file (generated CSV, downloaded result page) kept in memory before it
#: moves to disk.
SPOOL_MEMORY = 1024 * 1024
DEFAULT_TIMEOUT = 3600.0


def _pread(f: IO[bytes], offset: int, size: int) -> bytes:
    f.seek(offset)
    return f.read(size)


def _open_binary(path: str) -> IO[bytes]:
    return open(path, "rb")  # closed by _Source.close


def _spool() -> IO[bytes]:
    return tempfile.SpooledTemporaryFile(max_size=SPOOL_MEMORY)


class _Source:
    """Random access to the CSV being uploaded, so each part (and each resend) reads its range."""

    def __init__(
        self, data: bytes | bytearray | memoryview | None = None, f: IO[bytes] | None = None
    ) -> None:
        self._view = memoryview(data) if data is not None else None
        self._file = f

    def read_at(self, offset: int, size: int) -> bytes:
        if self._view is not None:
            return bytes(self._view[offset : offset + size])
        assert self._file is not None
        return _compat.to_thread(_pread, self._file, offset, size)

    def close(self) -> None:
        if self._file is not None:
            self._file.close()


def _job_path(version: str, kind: str, job_id: str, rest: str = "") -> str:
    """A job URL in the API version that created the job (another version returns 409)."""
    return f"/services/data/v{version}/jobs/{kind}/{check_record_id(job_id)}{rest}"


def _is_query(info: BulkJobInfo) -> bool:
    return info.operation in ("query", "queryAll")


def _event(info: BulkJobInfo) -> dict[str, Any]:
    return {
        "job_id": info.id,
        "operation": info.operation,
        "sobject": info.sobject,
        "state": info.state.value,
        "records_processed": info.records_processed,
        # Query job info has no numberRecordsFailed: report None, not 0.
        "records_failed": None if _is_query(info) else info.records_failed,
    }


def _failed(info: BulkJobInfo, hint: str | None = None) -> BulkJobFailed:
    detail = f": {info.error_message}" if info.error_message else ""
    return BulkJobFailed(
        f"Bulk job {info.id} ended in state {info.state.value}{detail}",
        job_id=info.id,
        state=info.state.value,
        error_message=info.error_message,
        operation=f"bulk.{'query' if _is_query(info) else 'ingest'}",
        sobject=info.sobject,
        hint=hint,
    )


def _read_csv(chunks: Iterator[bytes]) -> Iterator[dict[str, str]]:
    reader = CsvReader()
    for chunk in chunks:
        for row in reader.feed(chunk):
            yield row
    for row in reader.finish():
        yield row


def _file_chunks(f: IO[bytes]) -> Iterator[bytes]:
    while chunk := _compat.to_thread(f.read, CHUNK_SIZE):
        yield chunk


class _Jobs:
    """Status calls and polling shared by ingest jobs and query jobs."""

    def __init__(self, client: Salesforce, kind: str) -> None:
        self._sf = client
        self._kind = kind  # "ingest" or "query"

    def status(self, info: BulkJobInfo) -> BulkJobInfo:
        raw = self._sf._send(
            RequestSpec(
                "GET",
                _job_path(info.api_version, self._kind, info.id),
                operation=f"bulk.{self._kind}.status",
                sobject=info.sobject,
            )
        )
        new = parse_job_info(raw.json(), info.api_version)
        if (new.state, new.records_processed, new.records_failed) != (
            info.state,
            info.records_processed,
            info.records_failed,
        ):  # a state change or progress: long jobs report as they go
            self._sf._transport.emit("sf.bulk.job", _event(new))
        return new

    def set_state(self, info: BulkJobInfo, state: str, operation: str) -> BulkJobInfo:
        content, ctype = self._sf._transport.encode({"state": state})
        raw = self._sf._send(
            RequestSpec(
                "PATCH",
                _job_path(info.api_version, self._kind, info.id),
                content=content,
                content_type=ctype,
                operation=operation,
                sobject=info.sobject,
            )
        )
        new = parse_job_info(raw.json(), info.api_version)
        self._sf._transport.emit("sf.bulk.job", _event(new))
        return new

    def wait(
        self,
        infos: list[BulkJobInfo],
        poll: Backoff | None,
        timeout: float,
        hint: Callable[[BulkJobInfo], str | None] = lambda info: None,
    ) -> None:
        """Poll every unfinished job in ``infos`` (updated in place) until all are final.

        Raises:
            BulkJobFailed: a job ended ``Failed`` or ``Aborted``.
            BulkJobTimeout: the jobs didn't finish within ``timeout`` seconds.
        """
        if not timeout > 0:
            raise ValueError("timeout must be > 0 seconds")
        poll = poll or Backoff()
        started, slept, attempt = time.monotonic(), 0.0, 0
        while True:
            for n, info in enumerate(infos):
                if not info.state.is_final:
                    infos[n] = self.status(info)
            if all(i.state.is_final for i in infos):
                for info in infos:
                    if info.state in (BulkJobState.FAILED, BulkJobState.ABORTED):
                        raise _failed(info, hint(info))
                return
            left = timeout - max(time.monotonic() - started, slept)
            if left <= 0:
                waiting = next(i for i in infos if not i.state.is_final)
                raise BulkJobTimeout(
                    f"Bulk job {waiting.id} is still {waiting.state.value} after {timeout:g} s; "
                    "it keeps running in Salesforce",
                    job_id=waiting.id,
                    state=waiting.state.value,
                    operation=f"bulk.{self._kind}.wait",
                    sobject=waiting.sobject,
                )
            delay = min(poll.delay(attempt), left)
            attempt += 1
            self._sf._transport.sleep(delay)
            slept += delay


class IngestJob:
    """A Bulk API 2.0 ingest job, returned by ``sf.bulk.ingest()``.

    The upload is complete when you get the job, and Salesforce processes it in the background.
    Call :meth:`wait`, then read the results. If the data was larger than 100 MB, the client
    split it over several Salesforce jobs. This object then stands for all of them: ``ids``
    lists them, and the results iterate over every job in order.
    """

    def __init__(self, client: Salesforce, infos: Sequence[BulkJobInfo]) -> None:
        self._sf = client
        self._jobs = _Jobs(client, "ingest")
        self._infos = list(infos)

    def __repr__(self) -> str:
        info = self.info
        ids = ", ".join(self.ids)
        return f"<{type(self).__name__} {ids} {info.operation} {info.sobject} {info.state.value}>"

    @property
    def ids(self) -> tuple[str, ...]:
        """The Salesforce job ids, one per part of at most 100 MB."""
        return tuple(i.id for i in self._infos)

    @property
    def info(self) -> BulkJobInfo:
        """Status from the latest call: state, record counts and timing.

        For several jobs, the counts are summed and the state is the least finished one.
        """
        return combine_infos(self._infos)

    @property
    def parts(self) -> tuple[BulkJobInfo, ...]:
        """The status of each Salesforce job, in upload order."""
        return tuple(self._infos)

    def refresh(self) -> BulkJobInfo:
        """Get the current status of every unfinished job. Returns :attr:`info`."""
        for n, info in enumerate(self._infos):
            if not info.state.is_final:
                self._infos[n] = self._jobs.status(info)
        return self.info

    def wait(self, *, poll: Backoff | None = None, timeout: float = DEFAULT_TIMEOUT) -> BulkJobInfo:
        """Poll until every job is finished. Returns the final :attr:`info`.

        A job that ends ``JobComplete`` can still have failed records: read
        :meth:`failed_results` or ``info.records_failed``.

        Args:
            poll: How long to wait between status calls. Defaults to ``esf.Backoff()``
                (2 s, doubling up to 30 s).
            timeout: Seconds to wait in total.

        Raises:
            BulkJobFailed: a job ended ``Failed`` or ``Aborted``. ``unprocessed_records()``
                lists the rows that Salesforce didn't process.
            BulkJobTimeout: the jobs didn't finish in time. They keep running; call
                ``wait()`` again to keep waiting.

        Example:
            info = job.wait(poll=esf.Backoff(start=2, max=30), timeout=3600)
        """
        self._jobs.wait(self._infos, poll, timeout)
        return self.info

    def abort(self) -> BulkJobInfo:
        """Abort every job that isn't finished. Salesforce doesn't process aborted jobs."""
        for n, info in enumerate(self._infos):
            if not info.state.is_final:
                self._infos[n] = self._jobs.set_state(info, "Aborted", "bulk.ingest.abort")
        return self.info

    def successful_results(self) -> Iterator[dict[str, str]]:
        """Rows Salesforce saved: ``sf__Id``, ``sf__Created`` and the columns you uploaded.

        The rows are streamed and parsed as they arrive; their order is not the upload order.
        """
        for row in self._results("successfulResults/"):
            yield row

    def failed_results(self) -> Iterator[BulkFailure]:
        """Rows Salesforce rejected, with the parsed ``sf__Error`` as an :class:`ErrorDetail`.

        Example:
            for failure in job.failed_results():
                print(failure.error.error_code, failure.fields["Email"])
        """
        for row in self._results("failedResults/"):
            error = parse_bulk_error(row.pop("sf__Error", ""))
            record_id = row.pop("sf__Id", "") or None
            yield BulkFailure(error=error, id=record_id, fields=row)

    def unprocessed_records(self) -> Iterator[dict[str, str]]:
        """Rows Salesforce didn't process because a job failed or was aborted."""
        for row in self._results("unprocessedrecords/"):
            yield row

    def _results(self, what: str) -> Generator[dict[str, str], None]:
        for info in list(self._infos):
            raw = self._sf._send(
                RequestSpec(
                    "GET",
                    _job_path(info.api_version, "ingest", info.id, f"/{what}"),
                    headers=_CSV,
                    operation="bulk.ingest.results",
                    sobject=info.sobject,
                    expect_json=False,
                    stream_response=True,
                )
            )
            stream = raw.stream
            try:
                for row in _read_csv(stream.__iter__()):
                    yield row
            finally:
                stream.close()


def _query_sobject(soql: str) -> str | None:
    from ..client import _sobject_of  # pyright: ignore[reportPrivateUsage]

    return _sobject_of(soql)


def _query_hint(client: Salesforce, soql: str, message: str | None) -> str | None:
    """Name the components of compound fields in ``soql``, when the describe is cached."""
    sobject = _query_sobject(soql)
    describe = client._transport.cached_describe(client._runtime, sobject) if sobject else None
    return compound_hint(soql, describe, message)


def _check_parallel(parallel_downloads: int) -> None:
    if not isinstance(parallel_downloads, int) or parallel_downloads < 1:  # pyright: ignore[reportUnnecessaryIsInstance]
        raise ValueError("parallel_downloads must be an int >= 1")


def _nulls(row: dict[str, str]) -> dict[str, str | None]:
    return {k: (v if v != "" else None) for k, v in row.items()}


class ResultPage:
    """One page of query results, yielded by :meth:`QueryJob.pages`.

    The client downloads the whole page to a temporary file before it yields the page, so
    reading the rows makes no more calls. The file is closed when the iteration moves on to the
    next page or ends: read the rows before you ask for the next page.
    """

    def __init__(self, locator: str | None, next_locator: str | None, size: int | None, f: IO[bytes]) -> None:
        #: The locator that fetched this page. ``None`` for the first page.
        self.locator = locator
        #: The locator of the next page: save it after you've handled the rows, and pass it to
        #: ``pages(locator=...)`` to go on from there. ``None`` after the last page.
        self.next_locator = next_locator
        #: The number of rows in the page (``Sforce-NumberOfRecords``), if Salesforce sent it.
        self.size = size
        self._file = f

    def __repr__(self) -> str:
        return f"<{type(self).__name__} locator={self.locator!r} next_locator={self.next_locator!r}>"

    def rows(self) -> Iterator[dict[str, str | None]]:
        """The rows of the page, in order, read from the temporary file.

        Each call reads the page from the start.

        Raises:
            ValueError: the iteration has moved on and the page is closed.
        """
        f = self._file
        if f.closed:
            raise ValueError("this page is closed; read its rows before you ask for the next page")
        f.seek(0)
        for row in _read_csv(_file_chunks(f)):
            yield _nulls(row)

    def close(self) -> None:
        """Delete the temporary file. ``pages()`` does it for you when it moves on."""
        self._file.close()


class QueryJob:
    """A Bulk API 2.0 query job, returned by ``sf.bulk.start_query()`` and ``sf.bulk.query_job()``.

    The job runs in Salesforce. Call :meth:`wait`, then read the results with :meth:`rows`, or
    page by page with :meth:`pages` to resume a download later. ``id`` is enough to open the job
    again in another process.
    """

    def __init__(self, client: Salesforce, info: BulkJobInfo, soql: str | None = None) -> None:
        self._sf = client
        self._jobs = _Jobs(client, "query")
        self._info = info
        self._soql = soql  # known when this client created the job; used for error hints

    def __repr__(self) -> str:
        info = self._info
        return f"<{type(self).__name__} {info.id} {info.operation} {info.sobject} {info.state.value}>"

    @property
    def id(self) -> str:
        """The Salesforce job id. Pass it to ``sf.bulk.query_job()`` to open the job again."""
        return self._info.id

    @property
    def info(self) -> BulkJobInfo:
        """Status from the latest call: state, ``records_processed`` and timing."""
        return self._info

    def refresh(self) -> BulkJobInfo:
        """Get the current status, if the job isn't finished. Returns :attr:`info`."""
        if not self._info.state.is_final:
            self._info = self._jobs.status(self._info)
        return self._info

    def wait(self, *, poll: Backoff | None = None, timeout: float = DEFAULT_TIMEOUT) -> BulkJobInfo:
        """Poll until the job is finished. Returns the final :attr:`info`.

        Args:
            poll: How long to wait between status calls. Defaults to ``esf.Backoff()``
                (2 s, doubling up to 30 s).
            timeout: Seconds to wait in total.

        Raises:
            BulkJobFailed: the job ended ``Failed`` or ``Aborted``.
            BulkJobTimeout: the job didn't finish in time. It keeps running; call ``wait()``
                again to keep waiting.

        Example:
            info = job.wait(timeout=3600)
            print(info.records_processed)
        """
        soql = self._soql
        infos = [self._info]
        try:
            self._jobs.wait(
                infos, poll, timeout, lambda i: _query_hint(self._sf, soql, i.error_message) if soql else None
            )
        finally:
            self._info = infos[0]
        return self._info

    def abort(self) -> BulkJobInfo:
        """Abort the job if it isn't finished. Returns :attr:`info`."""
        if not self._info.state.is_final:
            self._info = self._jobs.set_state(self._info, "Aborted", "bulk.query.abort")
        return self._info

    def _check_complete(self) -> None:
        info = self._info
        if info.state is BulkJobState.JOB_COMPLETE:
            return
        if info.state in (BulkJobState.FAILED, BulkJobState.ABORTED):
            raise _failed(info)
        raise BulkJobNotComplete(
            f"Bulk job {info.id} is {info.state.value}; call wait() before you read the results",
            job_id=info.id,
            state=info.state.value,
            operation="bulk.query.results",
            sobject=info.sobject,
        )

    def rows(self, *, parallel_downloads: int = 1) -> Generator[dict[str, str | None], None]:
        """Yield every row of a complete job, in order.

        Rows are dicts with the selected fields as keys. Values are strings, and empty values
        are ``None``. The client reads each page as it arrives, so memory stays flat.

        Args:
            parallel_downloads: With more than 1, the client downloads up to this many result
                pages at the same time and still yields rows in order. Salesforce hands out at
                most five page URLs at a time, so values above 5 don't download more.

        Raises:
            BulkJobNotComplete: the job isn't ``JobComplete`` yet. Call :meth:`wait` first.
            BulkJobFailed: the job failed or was aborted.

        Example:
            job.wait()
            for row in job.rows(parallel_downloads=4):
                print(row["Id"])
        """
        _check_parallel(parallel_downloads)
        self._check_complete()
        info = self._info
        # resultPages needs API 58.0; the client supports 59.0 and later.
        n = parallel_downloads
        rows = _serial(self._sf, info) if n == 1 else _parallel(self._sf, info, n)
        try:
            for row in rows:
                yield _nulls(row)
        finally:
            rows.close()  # closes the open result stream if you stop early

    def pages(
        self, *, locator: str | None = None, max_records: int | None = None
    ) -> Iterator[ResultPage]:
        """Yield the results of a complete job page by page, so a download can resume.

        After you've handled the rows of a page, save ``page.next_locator``. To go on after a
        restart, open the job with ``sf.bulk.query_job(job_id)`` and pass the saved locator.
        A locator stays valid as long as the job exists, and a page can be read again.

        Args:
            locator: The ``next_locator`` of the last page you handled. ``None`` starts at the
                first page.
            max_records: The most rows per page. Salesforce picks the size when it's ``None``.
                Smaller pages mean less to download again after a restart.

        Raises:
            BulkJobNotComplete: the job isn't ``JobComplete`` yet. Call :meth:`wait` first.
            BulkJobFailed: the job failed or was aborted.

        Example:
            for page in job.pages(locator=saved, max_records=50_000):
                for row in page.rows():
                    print(row["Id"])
                saved = page.next_locator  # None after the last page
        """
        if locator is not None and (not isinstance(locator, str) or not locator.strip()):  # pyright: ignore[reportUnnecessaryIsInstance]
            raise ValueError("locator must be a non-empty string from page.next_locator, or None")
        if max_records is not None and (
            not isinstance(max_records, int) or isinstance(max_records, bool) or max_records < 1  # pyright: ignore[reportUnnecessaryIsInstance]
        ):
            raise ValueError("max_records must be an int >= 1, or None")
        self._check_complete()
        info = self._info
        path = _job_path(info.api_version, "query", info.id, "/results")
        while True:
            params: dict[str, str] = {}
            if locator is not None:
                params["locator"] = locator
            if max_records is not None:
                params["maxRecords"] = str(max_records)
            raw = _result_page(self._sf, info, path, params or None)
            f = _spool_stream(raw.stream)
            page = ResultPage(locator, parse_locator(raw.headers), parse_record_count(raw.headers), f)
            try:
                yield page
            finally:
                page.close()
            if page.next_locator is None:
                return
            locator = page.next_locator


def _result_page(
    client: Salesforce, info: BulkJobInfo, path: str, params: Mapping[str, str] | None
) -> Any:
    return client._send(
        RequestSpec(
            "GET",
            path,
            params=params,
            headers=_CSV,
            operation="bulk.query.results",
            sobject=info.sobject,
            expect_json=False,
            stream_response=True,
        )
    )


def _spool_stream(stream: Any) -> IO[bytes]:
    """Copy a streamed response body to a temporary file, then close the stream."""
    f = _spool()
    try:
        for chunk in stream:
            _compat.to_thread(f.write, chunk)
        f.seek(0)
    except BaseException:
        f.close()
        raise
    finally:
        stream.close()
    return f


def _serial(client: Salesforce, info: BulkJobInfo) -> Generator[dict[str, str], None]:
    """Follow ``Sforce-Locator`` one page at a time, parsing each page as it streams."""
    path = _job_path(info.api_version, "query", info.id, "/results")
    locator: str | None = None
    while True:
        raw = _result_page(client, info, path, {"locator": locator} if locator else None)
        stream = raw.stream
        try:
            for row in _read_csv(stream.__iter__()):
                yield row
        finally:
            stream.close()
        locator = parse_locator(raw.headers)
        if locator is None:
            return


def _download(client: Salesforce, info: BulkJobInfo, url: str) -> IO[bytes]:
    raw = _result_page(client, info, url, None)
    return _spool_stream(raw.stream)


def _parallel(
    client: Salesforce, info: BulkJobInfo, n: int
) -> Generator[dict[str, str], None]:
    """Download the pages of each ``resultPages`` batch at once, then yield them in order."""
    prefix = _job_path(info.api_version, "query", info.id, "/")
    next_url: str | None = _job_path(info.api_version, "query", info.id, "/resultPages")
    while next_url is not None:
        raw = client._send(
            RequestSpec("GET", next_url, operation="bulk.query.pages", sobject=info.sobject)
        )
        urls, next_url = parse_result_pages(raw.json(), prefix)

        settled = _compat.gather_settled(
            n, [functools.partial(_download, client, info, u) for u in urls]
        )
        files = [f for f in settled if not isinstance(f, Exception)]
        try:
            for item in settled:
                if isinstance(item, Exception):
                    raise item
            for f in files:
                for row in _read_csv(_file_chunks(f)):
                    yield row
        finally:
            for f in files:
                f.close()


class Bulk:
    """Bulk API 2.0: load or read large numbers of records with asynchronous jobs.

    Uploads and query results are streamed, so memory use stays flat whatever the data size.
    """

    def __init__(self, client: Salesforce) -> None:
        self._sf = client

    # --- ingest ----------------------------------------------------------------------------

    def ingest(
        self,
        sobject: str,
        operation: IngestOperation,
        *,
        rows: Iterable[Mapping[str, Any]] | str | os.PathLike[str] | bytes,
        external_id_field: str | None = None,
        line_ending: LineEnding = "LF",
        column_delimiter: ColumnDelimiter = "COMMA",
    ) -> IngestJob:
        """Create an ingest job, upload the data and mark the upload complete.

        Salesforce then processes the job in the background. The client splits data over
        100 MB into several jobs, as Salesforce advises. Each job gets the header row and only
        whole records.

        Args:
            sobject: The object to load, such as ``"Lead"``.
            operation: ``"insert"``, ``"update"``, ``"upsert"``, ``"delete"`` or
                ``"hardDelete"``.
            rows: The data: an iterable of dicts, the path of a CSV file, or CSV ``bytes``.
                For dicts, the keys of the first row are the columns. ``None`` (or ``""``) sets
                a field to null, and a missing key leaves the field unchanged. On insert, both
                give the field its default value. A CSV file must be UTF-8 and is streamed
                from disk; a byte order mark is removed.
            external_id_field: The external id field that matches records. Required for
                ``upsert``, not allowed otherwise.
            line_ending: ``"LF"`` or ``"CRLF"``: the line ending of your CSV, or the one the
                client writes for dict rows.
            column_delimiter: The delimiter of your CSV, or the one the client writes:
                ``"COMMA"``, ``"TAB"``, ``"PIPE"``, ``"SEMICOLON"``, ``"CARET"`` or
                ``"BACKQUOTE"``.

        Returns:
            The job. Call ``wait()`` on it, then read its results.

        Raises:
            ValueError: invalid arguments, the string ``"#N/A"`` in a row, a CSV that isn't
                UTF-8, has no data rows or uses the other line ending, or a record over 100 MB.
            SalesforceError: Salesforce rejected the job or the upload. The client aborts the
                job it was uploading. Jobs it finished before keep running; the message names
                them.

        Example:
            job = sf.bulk.ingest("Lead", "insert", rows=[{"LastName": "Doe", "Company": "Acme"}])
        """
        check_sobject(sobject)
        check_ingest(operation, external_id_field, line_ending, column_delimiter)
        source, header, parts = self._prepare(rows, line_ending, column_delimiter)
        done: list[BulkJobInfo] = []
        try:
            check_line_ending(header, line_ending)
            body = ingest_job_body(sobject, operation, external_id_field, line_ending, column_delimiter)
            for start, end in parts:
                info = self._create("ingest", body, sobject, None)
                try:
                    self._upload(info, source, header, start, end)
                    info = _Jobs(self._sf, "ingest").set_state(
                        info, "UploadComplete", "bulk.ingest.close"
                    )
                except Exception as exc:
                    try:
                        _Jobs(self._sf, "ingest").set_state(info, "Aborted", "bulk.ingest.abort")
                    except SalesforceError:
                        pass
                    if done and isinstance(exc, SalesforceError):
                        exc.message = (
                            f"{exc.message} (job {info.id} was aborted; jobs "
                            f"{', '.join(i.id for i in done)} were uploaded and keep running)"
                        )
                        exc.args = (exc.message,)
                    raise
                done.append(info)
        finally:
            source.close()
        return IngestJob(self._sf, done)

    def _prepare(
        self, rows: Any, line_ending: str, column_delimiter: str
    ) -> tuple[_Source, bytes, list[tuple[int, int]]]:
        """Scan (or write) the CSV and find the parts, before anything is sent."""
        cutter = CsvCutter(_bulk.MAX_PART_BYTES)
        if isinstance(rows, (bytes, bytearray, memoryview)):
            source = _Source(data=rows)  # pyright: ignore[reportUnknownArgumentType]
            view = memoryview(rows)  # pyright: ignore[reportUnknownArgumentType]
            for i in range(0, len(view), CHUNK_SIZE):
                cutter.feed(bytes(view[i : i + CHUNK_SIZE]))
        elif isinstance(rows, (str, os.PathLike)):
            f = _compat.to_thread(_open_binary, os.fspath(rows))  # pyright: ignore[reportUnknownArgumentType]
            source = _Source(f=f)
            try:
                for chunk in _file_chunks(f):
                    cutter.feed(chunk)
            except BaseException:
                source.close()
                raise
        elif isinstance(rows, Iterable):
            source = self._spool_rows(rows, cutter, line_ending, column_delimiter)  # pyright: ignore[reportUnknownArgumentType]
        else:
            raise TypeError(
                f"rows must be an iterable of dicts, a CSV path or CSV bytes, got {type(rows).__name__}"
            )
        try:
            header, parts = cutter.finish()
        except BaseException:
            source.close()
            raise
        return source, header, parts

    def _spool_rows(
        self, rows: Iterable[Mapping[str, Any]], cutter: CsvCutter, line_ending: str, column_delimiter: str
    ) -> _Source:
        encoder = RowEncoder(column_delimiter, line_ending)
        f = _spool()
        try:
            buf = bytearray()
            for row in rows:
                if encoder.columns is None:
                    buf += encoder.header(row)
                buf += encoder.encode(row)
                if len(buf) >= CHUNK_SIZE:
                    data = bytes(buf)
                    buf.clear()
                    cutter.feed(data)
                    _compat.to_thread(f.write, data)
            if encoder.columns is None:
                raise ValueError("rows is empty; there is nothing to upload")
            if buf:
                cutter.feed(bytes(buf))
                _compat.to_thread(f.write, bytes(buf))
        except BaseException:
            f.close()
            raise
        return _Source(f=f)

    def _create(
        self, kind: str, body: dict[str, Any], sobject: str | None, soql: str | None
    ) -> BulkJobInfo:
        content, ctype = self._sf._transport.encode(body)
        raw = self._sf._send(
            RequestSpec(
                "POST",
                f"jobs/{kind}",
                content=content,
                content_type=ctype,
                operation=f"bulk.{kind}.create",
                sobject=sobject,
                soql=soql,
            )
        )
        info = parse_job_info(raw.json(), self._sf.api_version)
        self._sf._transport.emit("sf.bulk.job", _event(info))
        return info

    def _upload(self, info: BulkJobInfo, source: _Source, header: bytes, start: int, end: int) -> None:
        """Stream one part to ``PUT jobs/ingest/{id}/batches``, gzipped when it's over 64 KiB.

        A gzipped body is sent with chunked transfer encoding: its size is only known at the
        end. Salesforce accepts gzipped uploads with ``Content-Length`` and chunked
        (big-bang.md §21 V40). The 100 MB split applies to the raw CSV either way.
        """
        size = len(header) + end - start
        compress = size > GZIP_THRESHOLD

        def raw() -> Iterator[bytes]:
            yield header
            offset = start
            while offset < end:
                data = source.read_at(offset, min(CHUNK_SIZE, end - offset))
                if not data:
                    raise ValueError("the CSV file got shorter during the upload")
                offset += len(data)
                yield data

        def gzipped() -> Iterator[bytes]:
            z = zlib.compressobj(GZIP_LEVEL, zlib.DEFLATED, 31)  # wbits 31: gzip container
            for data in raw():
                out = _compat.to_thread(z.compress, data)
                if out:
                    yield out
            yield z.flush()

        self._sf._send(
            RequestSpec(
                "PUT",
                _job_path(info.api_version, "ingest", info.id, "/batches"),
                content_type="text/csv; charset=UTF-8",
                headers={"Content-Encoding": "gzip"} if compress else {},
                body_stream=gzipped if compress else raw,
                body_length=None if compress else size,
                operation="bulk.ingest.upload",
                sobject=info.sobject,
                expect_json=False,
            )
        )

    # --- query -----------------------------------------------------------------------------

    def start_query(self, soql: str, *values: Any, include_deleted: bool = False) -> QueryJob:
        """Create a Bulk API 2.0 query job and return it without waiting.

        Salesforce runs the job in the background. Keep ``job.id`` to open the job again later,
        also from another process, with :meth:`query_job`. Salesforce keeps the results for
        7 days after the job completes.

        Args:
            soql: The query. ``{}`` placeholders are filled with ``values``, as in ``sf.query``.
            *values: Values for the ``{}`` placeholders.
            include_deleted: Use ``queryAll``: also deleted and archived records.

        Returns:
            The job. Call ``wait()`` on it, then read ``rows()`` or ``pages()``.

        Raises:
            ValueError: the query selects ``FIELDS(ALL)`` or ``FIELDS(CUSTOM)``, which query
                jobs don't support. The client raises it before it creates a job.
            RequestError: Salesforce rejected the job, for example with ``400 API_ERROR``
                because the query selects compound address or geolocation fields. ``hint``
                then names their components.

        Example:
            job = sf.bulk.start_query("SELECT Id, Name FROM Lead")
            print(job.id)  # store it, then open the job again with sf.bulk.query_job(job_id)
        """
        soql = soql_values(soql, values)
        check_bulk_query(soql)
        sobject = _query_sobject(soql)
        try:
            info = self._create("query", query_job_body(soql, include_deleted), sobject, soql)
        except SalesforceError as exc:
            if exc.hint is None:
                exc.hint = _query_hint(self._sf, soql, exc.message)
            raise
        return QueryJob(self._sf, info, soql)

    def query(
        self,
        soql: str,
        *values: Any,
        include_deleted: bool = False,
        parallel_downloads: int = 1,
        poll: Backoff | None = None,
        timeout: float = DEFAULT_TIMEOUT,
    ) -> Iterator[dict[str, str | None]]:
        """Run a Bulk API 2.0 query job and yield every row.

        The client creates the job, polls it until it's complete, and then streams the result
        CSV. Rows are dicts with the selected fields as keys (``"Owner.Name"`` for parent
        fields). Values are strings, and empty values are ``None``. To keep the job id, wait
        in another process or resume a download, use :meth:`start_query` instead.

        Args:
            soql: The query. ``{}`` placeholders are filled with ``values``, as in ``sf.query``.
            *values: Values for the ``{}`` placeholders.
            include_deleted: Use ``queryAll``: also deleted and archived records.
            parallel_downloads: With more than 1, the client downloads up to this many result
                pages at the same time and still yields rows in order. Salesforce hands out at
                most five page URLs at a time (``resultPages``, API 58.0 and later), so values
                above 5 don't download more. Pages that wait their turn are kept in temporary
                files, not in memory.
            poll: How long to wait between status calls. Defaults to ``esf.Backoff()``.
            timeout: Seconds to wait for the job to finish.

        Raises:
            ValueError: the query selects ``FIELDS(ALL)`` or ``FIELDS(CUSTOM)``, which query
                jobs don't support. The client raises it before it creates a job.
            RequestError: Salesforce rejected the job, for example with ``400 API_ERROR``
                because the query selects compound address or geolocation fields (also
                through ``FIELDS(STANDARD)``). ``hint`` then names their components.
            BulkJobFailed: the job failed or was aborted.
            BulkJobTimeout: the job didn't finish in time.

        Example:
            for row in sf.bulk.query("SELECT Id, Name FROM Lead", parallel_downloads=4):
                print(row["Name"])
        """
        _check_parallel(parallel_downloads)
        job = self.start_query(soql, *values, include_deleted=include_deleted)
        job.wait(poll=poll, timeout=timeout)
        rows = job.rows(parallel_downloads=parallel_downloads)
        try:
            for row in rows:
                yield row
        finally:
            rows.close()  # closes the open result stream if you stop early

    # --- open a job again ----------------------------------------------------------------------

    def query_job(self, job_id: str) -> QueryJob:
        """Open a query job by its id, for example in a worker after a restart.

        The client gets the job's current status. Later calls use the API version that created
        the job. Salesforce deletes a job 7 days after it finished.

        Raises:
            ValueError: ``job_id`` isn't a record id.
            NotFound: Salesforce has no query job with this id: the job was deleted, or the id
                belongs to an ingest job.

        Example:
            job = sf.bulk.query_job(job_id)
            job.wait()
        """
        info = self._get_job("query", job_id)
        # Salesforce answers 404 for the id of the other job kind (big-bang.md §21 V88); this
        # check only guards against a response for the wrong kind of job.
        if not _is_query(info):
            raise ValueError(f"job {info.id} is an ingest job; open it with sf.bulk.ingest_job()")
        return QueryJob(self._sf, info)

    def ingest_job(self, job_ids: Sequence[str]) -> IngestJob:
        """Open an ingest job by its ids: the ``ids`` of the job that ``ingest()`` returned.

        An upload over 100 MB runs as several Salesforce jobs. Pass all of their ids, in upload
        order, to get the same job back. The client gets the status of each one.

        Raises:
            TypeError: ``job_ids`` is a string, not a sequence of ids.
            ValueError: ``job_ids`` is empty, or an id isn't a record id.
            NotFound: Salesforce has no ingest job with one of the ids: the job was deleted, or
                the id belongs to a query job.

        Example:
            job = sf.bulk.ingest_job(saved_ids)
            job.wait()
        """
        if isinstance(job_ids, str):
            raise TypeError("job_ids must be a sequence of job ids, such as job.ids, not a string")
        ids = list(job_ids)
        if not ids:
            raise ValueError("job_ids is empty")
        for job_id in ids:
            check_record_id(job_id)
        infos: list[BulkJobInfo] = []
        for job_id in ids:
            info = self._get_job("ingest", job_id)
            if _is_query(info):
                raise ValueError(f"job {info.id} is a query job; open it with sf.bulk.query_job()")
            infos.append(info)
        return IngestJob(self._sf, infos)

    def _get_job(self, kind: str, job_id: str) -> BulkJobInfo:
        raw = self._sf._send(
            RequestSpec(
                "GET",
                f"jobs/{kind}/{check_record_id(job_id)}",
                operation=f"bulk.{kind}.status",
            )
        )
        return parse_job_info(raw.json(), self._sf.api_version)

    # --- helpers -----------------------------------------------------------------------------

    def expand_compound_fields(self, sobject: str, fields: Sequence[str]) -> list[str]:
        """Replace compound address and geolocation fields with their component fields.

        Bulk queries can't select compound fields. This reads the describe of ``sobject``
        (from the describe cache when fresh) and swaps each compound field for its parts.
        Other names stay as they are.

        Example:
            fields = sf.bulk.expand_compound_fields("Account", ["Id", "BillingAddress"])
            # ['Id', 'BillingStreet', 'BillingCity', 'BillingState', ...]
        """
        if isinstance(fields, str):
            raise TypeError("fields must be a list of field names, not a string")
        describe = self._sf.sobject(check_sobject(sobject)).describe()
        return _bulk.expand_compound_fields(describe, fields)
